pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 val1, uint256 val2) internal {
        vm.assume(true);
        uint256 before;
        try c.MinSum() returns (uint256 __r) { before = __r; } catch { return; }
        bool reverted;
        try c.SetMinSum(val2) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterVal;
        try c.MinSum() returns (uint256 __r) { afterVal = __r; } catch { return; }
        assertTrue(!reverted ? afterVal == val2 : afterVal == before);
    }

    function testFuzz_run(uint256 val1, uint256 val2) public {
        _run(val1, val2);
    }

    receive() external payable {}
}
